"""Same original miter, undef-aware weak temporal nondivergence lemma only."""
import json,hashlib,os,resource,subprocess,time
from pathlib import Path
R=Path(__file__).resolve().parents[1]
def sha(p):return hashlib.sha256(Path(p).read_bytes()).hexdigest()
def main():
 old=R/'experiments/prospective_external_family_source_equivalence_v1_2026-10-18';op=old/'protocol.json';p=json.loads(op.read_text());assert all(sha(k)==h for k,h in p['bindings'].items());tool=Path(next(k for k in p['bindings'] if k.endswith('/bin/yosys')));runtime=R/'experiments/prospective_external_family_runtime_v1_2026-10-18';env=os.environ.copy();lib=runtime/'tcl-root/usr/lib/x86_64-linux-gnu';env['LD_LIBRARY_PATH']=str(lib)+(os.pathsep+env['LD_LIBRARY_PATH'] if env.get('LD_LIBRARY_PATH') else '');out=R/'experiments/prospective_external_undef_nondivergence_v1_2026-10-18';out.mkdir();prefix=p['commands'][:p['commands'].index('equiv_simple -undef')];assert prefix[-2:]==['equiv_make gold gate equiv','hierarchy -top equiv'];commands=prefix+['write_json "'+str(out/'miter_before.json')+'"','equiv_induct -undef -seq 2','write_json "'+str(out/'miter_after.json')+'"','equiv_status -assert'];script=out/'commands.ys';script.write_text('\n'.join(commands)+'\n');bindings={**p['bindings'],str(op):sha(op),str(old/'commands.ys'):sha(old/'commands.ys'),str(Path(__file__).resolve()):sha(Path(__file__).resolve()),str(script):sha(script)}
 with (out/'equiv_induct_help.log').open('x') as log:code=subprocess.call([str(tool),'-Q','-T','-p','help equiv_induct'],cwd=out,env=env,stdout=log,stderr=subprocess.STDOUT)
 assert code==0;helptext=(out/'equiv_induct_help.log').read_text();assert "weak definition of 'equivalence'" in helptext;bindings[str(out/'equiv_induct_help.log')]=sha(out/'equiv_induct_help.log');protocol=dict(bindings=bindings,commands=commands,original_miter_prefix_byte_exact=True,AS_limit_bytes=8*2**30,timeout_seconds=None,scope='Weak undef-aware temporal nondivergence lemma on original unrestricted miter, no input/reset assumptions added. Tool assumes matching observable points for induction frames; this is not startup alignment or original full source equivalence. Never replaces original running proof or strict family-history gate.',original_source_equivalence_gate_satisfied_by_this_trial=False,strict_unseen_family_admitted=False,new_native_labels_read=False,new_placement_or_route_jobs=False);(out/'protocol.json').write_text(json.dumps(protocol,indent=2)+'\n')
 def limits():resource.setrlimit(resource.RLIMIT_AS,(8*2**30,8*2**30))
 tick=time.perf_counter()
 with (out/'check.log').open('x') as log:
  child=subprocess.Popen([str(tool),'-Q','-T','-s',str(script)],cwd=out,env=env,stdout=log,stderr=subprocess.STDOUT,preexec_fn=limits);stat=Path('/proc',str(child.pid),'stat').read_text().split(') ',1)[1].split();(out/'live_process.json').write_text(json.dumps(dict(pid=child.pid,startticks=stat[19]))+'\n');print('UNDEF_NONDIVERGENCE_CHILD',child.pid,stat[19],flush=True);code=child.wait()
 elapsed=time.perf_counter()-tick;text=(out/'check.log').read_text();before=json.loads((out/'miter_before.json').read_text())['modules']['equiv']['cells'];properties={n:c for n,c in before.items() if c['type']=='$equiv'};assert len(properties)==1970;assert not any(c['type']=='$assume' for c in before.values());afterpath=out/'miter_after.json';post=json.loads(afterpath.read_text())['modules']['equiv']['cells'] if afterpath.exists() else {};postprops={n:c for n,c in post.items() if c['type']=='$equiv'};proven=sum(c['connections']['A']==c['connections']['B'] for c in postprops.values());assert set(postprops)==set(properties) if post else True;assert all(sha(k)==h for k,h in bindings.items());files={str(f):sha(f) for f in out.iterdir() if f.is_file() and f.name not in ['live_process.json']};result=dict(status='undef_temporal_nondivergence_all1970_lemmas_pass' if code==0 and proven==1970 else 'undef_temporal_nondivergence_not_fully_proven',bindings=bindings,files=files,exit_status=code,properties_before=1970,properties_after=len(postprops),proven=proven,process_seconds=elapsed,no_assumption_cells_added=True,original_source_equivalence_gate_satisfied=False,strict_unseen_family_admitted=False,new_native_labels_read=False,scope=protocol['scope']);(out/'receipt.json').write_text(json.dumps(result,indent=2)+'\n');print('UNDEF_NONDIVERGENCE_TERMINAL',code,1970,proven,flush=True)
if __name__=='__main__':main()
